list_shipping_methods.code:
import {shippingMethods} from 'webcommander-sdk';

const response = await shippingMethods.listShippingMethods(client, {limit: 20});
for (const shippingMethod of response.map.shipping_methods) {
    console.log(shippingMethod.id, shippingMethod.name, shippingMethod.is_default);
}

